import{_ as a,o as r,c as o,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 28 章 扩展、定时任务与多端接入（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第28章 扩展、定时任务与多端接入（易懂版）.md","filePath":"easy/第28章 扩展、定时任务与多端接入（易懂版）.md"}'),d={name:"easy/第28章 扩展、定时任务与多端接入（易懂版）.md"};function l(s,t,n,i,h,_){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="第-28-章-扩展、定时任务与多端接入-易懂版" tabindex="-1">第 28 章 扩展、定时任务与多端接入（易懂版） <a class="header-anchor" href="#第-28-章-扩展、定时任务与多端接入-易懂版" aria-label="Permalink to &quot;第 28 章 扩展、定时任务与多端接入（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 <a href="./../bluebook/第五篇 平台能力全景/第 28 章 扩展、定时任务与多端接入.html">第 28 章 扩展、定时任务与多端接入（完整版）</a>。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>三件事：让它自己按点干活（定时）、能装外援（扩展）、手机上也能用（多端）。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><ul><li><strong>定时任务</strong> = 闹钟 + 自动执行：早上 9 点自己把日报整理好；</li><li><strong>扩展</strong> = 给手机装 App：需要新本事就装一个；</li><li><strong>多端接入</strong> = 换屏幕：电脑、局域网网页、手机，都是同一个我。</li></ul><h2 id="一、定时任务-最容易被忽视-但最省事" tabindex="-1">一、定时任务（最容易被忽视，但最省事） <a class="header-anchor" href="#一、定时任务-最容易被忽视-但最省事" aria-label="Permalink to &quot;一、定时任务（最容易被忽视，但最省事）&quot;">​</a></h2><p>规矩很简单：<strong>一个任务一个会话，先说清干什么、几点干、结果放哪。</strong></p><blockquote><p>&quot;每天早上 9 点，把【某个文件】里的新内容整理成一页摘要，写到【输出文件】。如果拿不到数据就标注，不要编造。&quot;</p></blockquote><p><strong>重要提醒</strong>：新建前先问一句&quot;现在有哪些定时任务？&quot;——<strong>避免建重复。</strong></p><h2 id="二、扩展与市场-缺什么装什么" tabindex="-1">二、扩展与市场（缺什么装什么） <a class="header-anchor" href="#二、扩展与市场-缺什么装什么" aria-label="Permalink to &quot;二、扩展与市场（缺什么装什么）&quot;">​</a></h2><p>需要新本事时，去市场找：</p><table tabindex="0"><thead><tr><th>市场</th><th>装什么</th></tr></thead><tbody><tr><td>助手市场</td><td>别人做好的专家助手</td></tr><tr><td>技能市场</td><td>别人做好的技能</td></tr><tr><td>MCP 市场</td><td>连外部工具（数据库、网盘、第三方服务）</td></tr></tbody></table><p><strong>原则：先看自带够不够，不够再装。</strong></p><h2 id="三、多端接入-在哪都能用" tabindex="-1">三、多端接入（在哪都能用） <a class="header-anchor" href="#三、多端接入-在哪都能用" aria-label="Permalink to &quot;三、多端接入（在哪都能用）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th>适合</th></tr></thead><tbody><tr><td>电脑客户端</td><td>默认方式</td><td>正经干活</td></tr><tr><td>局域网网页 (WebUI)</td><td>同一网络用浏览器打开</td><td>换台电脑接着干</td></tr><tr><td>Tailscale / 服务器</td><td>外网也能连</td><td>出差、手机远程</td></tr></tbody></table><p>还能把生成好的文件<strong>直接发到手机或聊天软件</strong>，人不在电脑前也能收活。</p><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 定时任务建重复——<strong>先查再建</strong>；</li><li>❌ 装一堆不用的扩展——<strong>一次装一个，用顺了再装下一个</strong>；</li><li>❌ 忘了输出放哪——<strong>定时任务必须写清&quot;结果写到哪个文件&quot;</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>定时 = 让它自己干；扩展 = 让它多会一点；多端 = 让你在哪都能用。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>问自己：<strong>我每天有没有一件&quot;重复、固定、不费脑&quot;的事？</strong> 有的话，就该把它变成定时任务。</p><p>👉 <a href="./../easy/">回到易懂版首页，按你的问题找入口 🏠</a></p>',24)])])}const p=a(d,[["render",l]]);export{u as __pageData,p as default};
